const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

async function main() {
  const ledger = new Ledger();
  const receipts = await Promise.all(Array.from({ length: 20 }, () => ledger.apply('shop', 'sale', 123)));
  assert.ok(receipts.every(r => r === receipts[0]));
  await assert.rejects(ledger.apply('shop', 'sale', 124), { message: 'key conflict' });
  assert.equal(ledger.entries.length, 1);
  assert.notEqual(await ledger.apply('other', 'sale', 123), receipts[0]);
  // Composite keys must not collide through concatenation.
  assert.notEqual(await ledger.apply('a:b', 'c', 1), await ledger.apply('a', 'b:c', 1));

  const retryLedger = new Ledger();
  let applies = 0;
  const apply = retryLedger.apply.bind(retryLedger);
  retryLedger.apply = (...args) => { applies++; return apply(...args); };
  const acknowledgements = [];
  const service = new PaymentService(retryLedger, {
    acknowledge: async r => {
      acknowledgements.push(r);
      if (acknowledgements.length < 3) throw new Transient('retry');
    }
  });
  const receipt = await service.pay('shop', 'sale', 123);
  assert.equal(applies, 1);
  assert.equal(retryLedger.entries.length, 1);
  assert.equal(acknowledgements.length, 3);
  assert.ok(acknowledgements.every(r => r === receipt));
  assert.equal(await service.pay('shop', 'sale', 123), receipt);
  await assert.rejects(service.pay('shop', 'sale', 124), { message: 'key conflict' });
  assert.equal(acknowledgements.length, 4);

  // Keep acknowledgements pending while equal and conflicting payments arrive.
  const concurrentLedger = new Ledger();
  let release;
  const pending = new Promise(resolve => { release = resolve; });
  const concurrentReceipts = [];
  const concurrentService = new PaymentService(concurrentLedger, {
    acknowledge: async r => { concurrentReceipts.push(r); await pending; }
  });
  const first = concurrentService.pay('shop', 'sale', 123);
  const second = concurrentService.pay('shop', 'sale', 123);
  await assert.rejects(concurrentService.pay('shop', 'sale', 124), { message: 'key conflict' });
  assert.equal(concurrentLedger.entries.length, 1);
  assert.equal(concurrentReceipts.length, 2);
  release();
  assert.equal(await first, await second);

  for (const attempts of [1, 2, 3, 4, 5]) {
    const failures = Array.from({ length: attempts }, (_, i) => new Transient(`failure ${i}`));
    const exhaustedLedger = new Ledger();
    let calls = 0;
    const exhausted = new PaymentService(exhaustedLedger, {
      acknowledge: async () => { throw failures[calls++]; }
    });
    await assert.rejects(exhausted.pay('shop', 'sale', 123, attempts), e => e === failures[attempts - 1]);
    assert.equal(calls, attempts);
    assert.equal(exhaustedLedger.entries.length, 1);
    const recovery = new PaymentService(exhaustedLedger, { acknowledge: async () => {} });
    assert.equal(await recovery.pay('shop', 'sale', 123), exhaustedLedger.entries[0]);
  }

  const permanent = new Error('permanent');
  let calls = 0;
  const noRetry = new PaymentService(new Ledger(), {
    acknowledge: async () => { calls++; throw permanent; }
  });
  await assert.rejects(noRetry.pay('shop', 'sale', 123, 5), e => e === permanent);
  assert.equal(calls, 1);

  const invalid = [
    ['', 'sale', 123, 3], ['shop', '', 123, 3],
    [null, 'sale', 123, 3], ['shop', 1, 123, 3],
    ...[0, -1, 1.5, NaN, Infinity, '123'].map(c => ['shop', 'sale', c, 3]),
    ...[0, -1, 6, 1.5, NaN, Infinity, null, '3'].map(a => ['shop', 'sale', 123, a])
  ];
  let actions = 0;
  const validationService = new PaymentService(
    { apply: async () => { actions++; throw new Error('unexpected ledger action'); } },
    { acknowledge: async () => { actions++; } }
  );
  for (const args of invalid) {
    await assert.rejects(validationService.pay(...args), { message: 'invalid payment' });
  }
  assert.equal(actions, 0);
  const invalidLedger = new Ledger();
  for (const args of invalid.filter(args => args[3] === 3)) {
    await assert.rejects(invalidLedger.apply(...args), { message: 'invalid payment' });
  }
  assert.equal(invalidLedger.entries.length, 0);
}

main().catch(error => { console.error(error); process.exitCode = 1; });
EOF
